package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsGrand decimal.Decimal = decimal.NewFromInt(0) // PIC 9(10)V99 len=12 = 0
var WsNewCount int64 = 0    // PIC 99 len=2 = 0
var WsShipCount int64 = 0   // PIC 99 len=2 = 0
var WsCancelCount int64 = 0 // PIC 99 len=2 = 0
var WsInvalid int64 = 0     // PIC 99 len=2 = 0
var WsBadQty int64 = 0      // PIC 99 len=2 = 0
var WsQtyEd string          // PIC ZZ9 len=3
var WsPriceEd string        // PIC Z,ZZ9.99 len=8
var WsTotalEd string        // PIC ZZ,ZZZ,ZZ9.99 len=13
var WsGrandEd string        // PIC Z,ZZZ,ZZZ,ZZ9.99 len=16

var curRec OrderRec
var inputLines []string
var inputPos int

func parseNum(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	var n int64
	for i := 0; i < len(t); i++ {
		c := t[i]
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int64(c-'0')
	}
	return n
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	cents := v.Shift(2).IntPart()
	const mod int64 = 10000000000 // 10^10
	cents = cents % mod
	return decimal.New(cents, -2)
}

func storeGrand(v decimal.Decimal) decimal.Decimal {
	cents := v.Shift(2).IntPart()
	const mod int64 = 1000000000000 // 10^12
	cents = cents % mod
	return decimal.New(cents, -2)
}

func formatQtyEd(q int64) string {
	m := q % 1000
	if m < 0 {
		m = -m
	}
	digits := fmt.Sprintf("%03d", m)
	k := 3
	for i := 0; i < 3; i++ {
		if digits[i] != '0' {
			k = i
			break
		}
	}
	var out [3]byte
	if 0 < k {
		out[0] = ' '
	} else {
		out[0] = digits[0]
	}
	if 1 < k {
		out[1] = ' '
	} else {
		out[1] = digits[1]
	}
	out[2] = digits[2]
	return string(out[:])
}

func formatPriceEd(v decimal.Decimal) string {
	cents := v.Shift(2).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	intMod := intPart % 10000
	digits := fmt.Sprintf("%04d", intMod)
	k := 4
	for i := 0; i < 4; i++ {
		if digits[i] != '0' {
			k = i
			break
		}
	}
	var out [8]byte
	if 0 < k {
		out[0] = ' '
	} else {
		out[0] = digits[0]
	}
	if k >= 1 {
		out[1] = ' '
	} else {
		out[1] = ','
	}
	if 1 < k {
		out[2] = ' '
	} else {
		out[2] = digits[1]
	}
	if 2 < k {
		out[3] = ' '
	} else {
		out[3] = digits[2]
	}
	out[4] = digits[3]
	out[5] = '.'
	out[6] = byte('0' + frac/10)
	out[7] = byte('0' + frac%10)
	return string(out[:])
}

func formatTotalEd(v decimal.Decimal) string {
	cents := v.Shift(2).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	intMod := intPart % 100000000
	digits := fmt.Sprintf("%08d", intMod)
	k := 8
	for i := 0; i < 8; i++ {
		if digits[i] != '0' {
			k = i
			break
		}
	}
	var out [13]byte
	if 0 < k {
		out[0] = ' '
	} else {
		out[0] = digits[0]
	}
	if 1 < k {
		out[1] = ' '
	} else {
		out[1] = digits[1]
	}
	if k >= 2 {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	if 2 < k {
		out[3] = ' '
	} else {
		out[3] = digits[2]
	}
	if 3 < k {
		out[4] = ' '
	} else {
		out[4] = digits[3]
	}
	if 4 < k {
		out[5] = ' '
	} else {
		out[5] = digits[4]
	}
	if k >= 5 {
		out[6] = ' '
	} else {
		out[6] = ','
	}
	if 5 < k {
		out[7] = ' '
	} else {
		out[7] = digits[5]
	}
	if 6 < k {
		out[8] = ' '
	} else {
		out[8] = digits[6]
	}
	out[9] = digits[7]
	out[10] = '.'
	out[11] = byte('0' + frac/10)
	out[12] = byte('0' + frac%10)
	return string(out[:])
}

func formatGrandEd(v decimal.Decimal) string {
	cents := v.Shift(2).IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	intMod := intPart % 10000000000
	digits := fmt.Sprintf("%010d", intMod)
	k := 10
	for i := 0; i < 10; i++ {
		if digits[i] != '0' {
			k = i
			break
		}
	}
	var out [16]byte
	if 0 < k {
		out[0] = ' '
	} else {
		out[0] = digits[0]
	}
	if k >= 1 {
		out[1] = ' '
	} else {
		out[1] = ','
	}
	if 1 < k {
		out[2] = ' '
	} else {
		out[2] = digits[1]
	}
	if 2 < k {
		out[3] = ' '
	} else {
		out[3] = digits[2]
	}
	if 3 < k {
		out[4] = ' '
	} else {
		out[4] = digits[3]
	}
	if k >= 4 {
		out[5] = ' '
	} else {
		out[5] = ','
	}
	if 4 < k {
		out[6] = ' '
	} else {
		out[6] = digits[4]
	}
	if 5 < k {
		out[7] = ' '
	} else {
		out[7] = digits[5]
	}
	if 6 < k {
		out[8] = ' '
	} else {
		out[8] = digits[6]
	}
	if k >= 7 {
		out[9] = ' '
	} else {
		out[9] = ','
	}
	if 7 < k {
		out[10] = ' '
	} else {
		out[10] = digits[7]
	}
	if 8 < k {
		out[11] = ' '
	} else {
		out[11] = digits[8]
	}
	out[12] = digits[9]
	out[13] = '.'
	out[14] = byte('0' + frac/10)
	out[15] = byte('0' + frac%10)
	return string(out[:])
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	inputLines = nil
	inputPos = 0
	for scanner.Scan() {
		line := scanner.Text()
		inputLines = append(inputLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	f.Close()
	WsEofFlag = "N"
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if inputPos >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	inputPos++
	if len(line) > 15 {
		line = line[:15]
	} else if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	curRec.OrId = line[0:5]
	curRec.OrStat = line[5:6]
	curRec.OrQty = parseNum(line[6:9])
	curRec.OrPrice = decimal.New(parseNum(line[9:15]), -2)
}

func ProcessPara() {
	WsTotal = decimal.NewFromInt(0)
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Fprintln(os.Stdout, curRec.OrId+" BAD QTY")
	} else if curRec.OrStat == "N" {
		q := decimal.NewFromInt(curRec.OrQty)
		v := q.Mul(curRec.OrPrice)
		v = v.Truncate(2)
		WsTotal = storeTotal(v)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "S" {
		q := decimal.NewFromInt(curRec.OrQty)
		rate := decimal.New(105, -2)
		v := q.Mul(curRec.OrPrice).Mul(rate)
		v = v.Round(2)
		WsTotal = storeTotal(v)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Fprintln(os.Stdout, curRec.OrId+" BAD STATUS "+curRec.OrStat)
	}
	WsGrand = storeGrand(WsGrand.Add(WsTotal).Truncate(2))
	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatQtyEd(curRec.OrQty)
	WsPriceEd = formatPriceEd(curRec.OrPrice)
	WsTotalEd = formatTotalEd(WsTotal)
	fmt.Fprintln(os.Stdout, curRec.OrId+" "+curRec.OrStat+" "+WsQtyEd+" "+WsPriceEd+" "+WsTotalEd)
}

func SummaryPara() {
	WsGrandEd = formatGrandEd(WsGrand)
	fmt.Fprintln(os.Stdout, "NEW: "+fmt.Sprintf("%02d", WsNewCount)+" SHIPPED: "+fmt.Sprintf("%02d", WsShipCount)+" CANCELLED: "+fmt.Sprintf("%02d", WsCancelCount))
	fmt.Fprintln(os.Stdout, "INVALID: "+fmt.Sprintf("%02d", WsInvalid)+" BAD QTY: "+fmt.Sprintf("%02d", WsBadQty))
	fmt.Fprintln(os.Stdout, "GRAND TOTAL: "+WsGrandEd)
}

func main() {
	MainPara()
}
